export class MissingRowError extends Error {}
export function returnNull(row) { return row === null ? null : row.id; }
export function throwMissing(row) { if (row === null) throw new MissingRowError('missing row'); return row.id; }

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { returnNull, throwMissing, MissingRowError } from '../src/policies.js';
test('null policies disagree', () => { assert.equal(returnNull(null), null); assert.throws(() => throwMissing(null), MissingRowError); });
test('existing row policies agree', () => { assert.equal(returnNull({id:42}), 42); assert.equal(throwMissing({id:42}), 42); });
